<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {paymentApi,type RegistrationOrder,type RefundOrder,formatMoney} from '../api/payment';
const registrations=ref<RegistrationOrder[]>([]),refunds=ref<RefundOrder[]>([]),loading=ref(true),error=ref(''),filter=ref('');const labels:Record<string,string>={PENDING_PAYMENT:'待支付',PAID:'已支付',CLOSED:'已关闭',CREATED:'已创建退款',PENDING:'退款处理中',SUCCESS:'退款成功',FAILED:'退款处理异常'};
const rows=computed(()=>registrations.value.filter(x=>!filter.value||x.status===filter.value));async function load(){loading.value=true;try{const [r,f]=await Promise.all([paymentApi.registrations(),paymentApi.refunds()]);registrations.value=r.data.data.records;refunds.value=f.data.data.records;error.value='';}catch{error.value='加载缴费信息失败，请稍后刷新。'}finally{loading.value=false;}}
onMounted(load);
</script><template><section class="page"><h1>我的缴费</h1><p>预约、收费和退款状态分别展示，以服务端结果为准。</p><p v-if="error" role="alert">{{error}} <button @click="load">刷新</button></p><div><button v-for="x in [['','全部'],['PENDING_PAYMENT','待支付'],['PAID','已支付'],['CLOSED','已关闭']]" :key="x[0]" @click="filter=x[0]">{{x[1]}}</button></div><p v-if="loading">正在加载…</p><p v-else-if="!rows.length">暂无缴费订单。</p><article v-for="o in rows" :key="o.id" class="card"><strong>{{o.orderNo}}</strong><p>挂号费：{{formatMoney(o.amountCent,o.currency)}} · {{labels[o.status]||o.status}}</p><p>支付截止：{{o.paymentDeadline}}</p><p v-if="o.refundedAmountCent">已退款：{{formatMoney(o.refundedAmountCent,o.currency)}}；剩余可退：{{formatMoney(o.remainingRefundableCent,o.currency)}}（{{o.settlementStatus}}）</p></article><h2>退款进度</h2><p v-if="!refunds.length">暂无退款记录。</p><article v-for="r in refunds" :key="r.id" class="card"><strong>{{r.refundNo}}</strong><p>{{formatMoney(r.amountCent,r.currency)}} · {{labels[r.status]||r.status}}</p><p>原因：{{r.reasonCode}} · 申请时间：{{r.requestedAt||'--'}}</p></article></section></template><style scoped>.card{margin:12px 0;padding:14px;border:1px solid #dce6ef;border-radius:10px}button{margin:0 6px 8px 0}</style>
